export interface MenuItem {
  id: string;
  category: string;
  name: string;
  price: number;
  description?: string;
  image?: string;
  isSpicy?: boolean;
}

export interface CartItem extends MenuItem {
  quantity: number;
  note?: string;
}

export interface LocationState {
  lat: number;
  lng: number;
  address?: string;
}

export interface OrderDetails {
  customerName: string;
  customerPhone: string;
  location: LocationState | null;
  items: CartItem[];
  total: number;
}

import * as XLSX from 'xlsx';
import { MenuItem } from '../types';

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vQHMMZknmvaNUkgBWkWnxtqRiDkgYfCcNcWuvUhH2uVSfqOOwPL232u566GkkusqA/pub?output=xlsx';

export const fetchMenuFromSheet = async (): Promise<MenuItem[]> => {
  try {
    const response = await fetch(SHEET_URL);
    if (!response.ok) {
      throw new Error('Failed to fetch menu data');
    }

    const arrayBuffer = await response.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });

    // Assume the first sheet is the menu
    const sheetName = workbook.SheetNames[0];
    const sheet = workbook.Sheets[sheetName];

    // Convert to JSON
    const rawData = XLSX.utils.sheet_to_json<any>(sheet);

    // Normalize keys and map to our MenuItem type
    // We try to be flexible with column names based on common practices
    return rawData.map((row, index) => {
      // Helper to find value regardless of case
      const getValue = (keys: string[]) => {
        const foundKey = Object.keys(row).find(k => keys.includes(k.toLowerCase()));
        return foundKey ? row[foundKey] : undefined;
      };

      const name = getValue(['name', 'menu', 'item', 'food', 'ชื่อเมนู', 'รายการ']);
      const price = getValue(['price', 'cost', 'ราคา']);
      const category = getValue(['category', 'type', 'หมวดหมู่', 'ประเภท']) || 'General';
      const desc = getValue(['description', 'detail', 'รายละเอียด', 'ส่วนประกอบ']);
      const img = getValue(['image', 'img', 'url', 'photo', 'รูปภาพ']);

      return {
        id: `item-${index}`,
        name: name || `Menu Item ${index + 1}`,
        price: Number(price) || 0,
        category: String(category),
        description: desc ? String(desc) : undefined,
        image: img ? String(img) : `https://picsum.photos/seed/${index}/300/200`,
        isSpicy: String(name).includes('Spicy') || String(desc).includes('พริก') || String(name).includes('ต้มยำ'),
      };
    }).filter(item => item.name && item.price > 0); // Filter out empty or invalid rows

  } catch (error) {
    console.error("Error loading menu:", error);
    // Return a fallback menu if the sheet fails (for demo stability)
    return [
      { id: '1', name: 'ข้าวกะเพราไก่ไข่ดาว', price: 60, category: 'อาหารจานเดียว', description: 'เผ็ดจัดจ้าน', isSpicy: true, image: 'https://picsum.photos/seed/krapow/300/200' },
      { id: '2', name: 'ข้าวผัดหมู', price: 55, category: 'อาหารจานเดียว', description: 'ผัดหอมกะทะ', isSpicy: false, image: 'https://picsum.photos/seed/friedrice/300/200' },
      { id: '3', name: 'ต้มยำกุ้ง', price: 120, category: 'กับข้าว', description: 'น้ำข้น', isSpicy: true, image: 'https://picsum.photos/seed/tomyum/300/200' },
    ];
  }
};

import { GoogleGenAI } from "@google/genai";
import { MenuItem } from '../types';

let geminiClient: GoogleGenAI | null = null;

const getClient = () => {
  if (!geminiClient && process.env.API_KEY) {
    geminiClient = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return geminiClient;
};

export const getFoodRecommendation = async (userQuery: string, menu: MenuItem[]): Promise<string> => {
  const client = getClient();
  if (!client) return "กรุณาตั้งค่า API KEY เพื่อใช้งาน AI (Please configure API Key)";

  // Optimize token usage by sending a simplified menu list
  const simplifiedMenu = menu.map(m => `${m.name} (${m.price} THB) [${m.category}] - ${m.description || ''}`).join('\n');

  const prompt = `
    You are a helpful, cheerful waiter at a Thai restaurant called "ArhanDuan".
    Here is our current menu:
    ---
    ${simplifiedMenu}
    ---

    The customer asks: "${userQuery}"

    Please recommend 1-3 items from the menu that match their request. 
    Explain why you recommend them briefly.
    If the requested item is not on the menu, politely apologize and suggest the closest alternative.
    Answer in Thai. Keep it short and friendly.
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text || "ขออภัย ระบบขัดข้องชั่วคราว (AI Error)";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "ขออภัย ไม่สามารถเชื่อมต่อกับ AI ได้ในขณะนี้";
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { MapContainer, TileLayer, Marker, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { LocationState } from '../types';

// Fix for Leaflet default icon issues in React
import icon from 'leaflet/dist/images/marker-icon.png';
import iconShadow from 'leaflet/dist/images/marker-shadow.png';

let DefaultIcon = L.icon({
    iconUrl: icon,
    shadowUrl: iconShadow,
    iconSize: [25, 41],
    iconAnchor: [12, 41]
});

L.Marker.prototype.options.icon = DefaultIcon;

interface MapPickerProps {
  onLocationSelect: (loc: LocationState) => void;
  initialLocation?: LocationState | null;
}

const LocationMarker: React.FC<{ onSelect: (lat: number, lng: number) => void, position: L.LatLng | null }> = ({ onSelect, position }) => {
  const map = useMapEvents({
    click(e) {
      onSelect(e.latlng.lat, e.latlng.lng);
      map.flyTo(e.latlng, map.getZoom());
    },
    locationfound(e) {
      onSelect(e.latlng.lat, e.latlng.lng);
      map.flyTo(e.latlng, 15);
    },
  });

  // Locate user on first load
  useEffect(() => {
    if (!position) {
      map.locate();
    }
  }, [map, position]);

  return position === null ? null : (
    <Marker position={position} />
  );
};

export const MapPicker: React.FC<MapPickerProps> = ({ onLocationSelect, initialLocation }) => {
  const [position, setPosition] = useState<L.LatLng | null>(
    initialLocation ? new L.LatLng(initialLocation.lat, initialLocation.lng) : null
  );

  const handleSelect = (lat: number, lng: number) => {
    const newPos = new L.LatLng(lat, lng);
    setPosition(newPos);
    onLocationSelect({ lat, lng, address: `Lat: ${lat.toFixed(4)}, Lng: ${lng.toFixed(4)}` });
  };

  // Bangkok center default
  const defaultCenter = [13.7563, 100.5018] as L.LatLngExpression;

  return (
    <div className="h-64 w-full rounded-lg overflow-hidden border-2 border-orange-200 shadow-inner">
      <MapContainer center={defaultCenter} zoom={13} scrollWheelZoom={true} style={{ height: '100%', width: '100%' }}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <LocationMarker onSelect={handleSelect} position={position} />
      </MapContainer>
      <div className="text-xs text-center text-gray-500 mt-1">
        *แตะที่แผนที่เพื่อปักหมุดจุดส่งอาหาร (Tap map to pin location)
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ShoppingCart, MapPin, Send, MessageCircle, X, Plus, Minus, Search, Loader2, Info } from 'lucide-react';
import { MenuItem, CartItem, LocationState } from './types';
import { fetchMenuFromSheet } from './services/menuService';
import { getFoodRecommendation } from './services/geminiService';
import { MapPicker } from './components/MapPicker';

// Default Merchant Line ID (replace if known)
const DEFAULT_LINE_ID = ""; // User can fill this in, or hardcode it

const App: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  // Checkout State
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [location, setLocation] = useState<LocationState | null>(null);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [showAi, setShowAi] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      const data = await fetchMenuFromSheet();
      setMenu(data);
      setLoading(false);
    };
    loadData();
  }, []);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQ = item.quantity + delta;
        return newQ > 0 ? { ...item, quantity: newQ } : item;
      }
      return item;
    }));
  };

  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    const answer = await getFoodRecommendation(aiQuery, menu);
    setAiResponse(answer);
    setIsAiLoading(false);
  };

  const generateLineMessage = () => {
    let msg = `🛒 *New Order from ArhanDuan*\n\n`;
    msg += `👤 Customer: ${customerName}\n`;
    msg += `📞 Tel: ${customerPhone}\n`;
    msg += `📍 Location: ${location ? `https://www.google.com/maps?q=${location.lat},${location.lng}` : 'Not provided'}\n\n`;
    msg += `📋 *Items:*\n`;
    cart.forEach(item => {
      msg += `- ${item.name} x${item.quantity} (${item.price * item.quantity}฿)\n`;
    });
    msg += `\n💰 *Total: ${total} THB*`;

    // Encode for URL
    return encodeURIComponent(msg);
  };

  const sendToLine = () => {
    if (!customerName || !customerPhone || cart.length === 0) {
      alert("Please fill in your name, phone and select items.");
      return;
    }
    const message = generateLineMessage();
    // Use the generic line text share scheme. 
    // This allows the user to pick the recipient (the Merchant's OA).
    window.open(`https://line.me/R/msg/text/?${message}`, '_blank');
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-orange-50">
        <div className="text-center">
          <Loader2 className="w-10 h-10 animate-spin text-orange-500 mx-auto mb-2" />
          <p className="text-orange-600 font-medium">กำลังโหลดเมนูอร่อยๆ...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-24 relative max-w-5xl mx-auto bg-white shadow-xl min-h-screen">

      {/* Header */}
      <header className="sticky top-0 z-40 bg-orange-600 text-white p-4 shadow-md flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">อาหารด่วน! 🛵</h1>
          <p className="text-xs text-orange-100">สั่งง่าย ส่งไว อร่อยถูกใจ</p>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setShowAi(!showAi)}
                className="p-2 bg-white/20 rounded-full hover:bg-white/30 transition"
            >
                <MessageCircle size={24} />
            </button>
            <button 
                onClick={() => setIsCartOpen(true)}
                className="relative p-2 bg-white/20 rounded-full hover:bg-white/30 transition"
            >
                <ShoppingCart size={24} />
                {cart.length > 0 && (
                    <span className="absolute top-0 right-0 bg-red-500 text-white text-xs font-bold w-5 h-5 rounded-full flex items-center justify-center border-2 border-orange-600">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                    </span>
                )}
            </button>
        </div>
      </header>

      {/* AI Assistant Panel */}
      {showAi && (
        <div className="bg-orange-50 p-4 border-b border-orange-200">
            <h3 className="font-bold text-orange-800 mb-2 flex items-center gap-2">
                <Info size={16}/> ผู้ช่วยแนะนำอาหาร (AI Waiter)
            </h3>
            <div className="flex gap-2 mb-3">
                <input 
                    type="text" 
                    value={aiQuery}
                    onChange={(e) => setAiQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()}
                    placeholder="เช่น อยากทานของเผ็ดๆ, แนะนำเมนูไก่หน่อย"
                    className="flex-1 p-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-orange-400"
                />
                <button 
                    onClick={handleAiAsk}
                    disabled={isAiLoading}
                    className="bg-orange-500 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-orange-600 disabled:opacity-50"
                >
                    {isAiLoading ? <Loader2 className="animate-spin w-4 h-4"/> : 'ถาม'}
                </button>
            </div>
            {aiResponse && (
                <div className="bg-white p-3 rounded-lg text-sm text-gray-700 shadow-sm border border-orange-100 whitespace-pre-wrap">
                    {aiResponse}
                </div>
            )}
        </div>
      )}

      {/* Menu Grid */}
      <main className="p-4">
        <h2 className="text-xl font-bold text-gray-800 mb-4">เมนูแนะนำ</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {menu.map(item => (
            <div key={item.id} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-md transition">
              <div className="h-40 w-full overflow-hidden bg-gray-200 relative">
                 <img src={item.image} alt={item.name} className="w-full h-full object-cover hover:scale-105 transition duration-500" />
                 {item.isSpicy && (
                     <span className="absolute top-2 right-2 bg-red-500 text-white text-[10px] px-2 py-1 rounded-full font-bold shadow-sm">
                         Spicy 🌶️
                     </span>
                 )}
              </div>
              <div className="p-4">
                <div className="flex justify-between items-start mb-1">
                    <h3 className="font-bold text-gray-800 text-lg leading-tight">{item.name}</h3>
                    <span className="font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded-md text-sm whitespace-nowrap">{item.price} ฿</span>
                </div>
                <p className="text-gray-500 text-sm mb-4 line-clamp-2 min-h-[2.5rem]">{item.description || 'อร่อยต้องลอง!'}</p>
                <button 
                  onClick={() => addToCart(item)}
                  className="w-full bg-orange-100 text-orange-700 py-2 rounded-lg font-semibold hover:bg-orange-200 active:bg-orange-300 transition flex items-center justify-center gap-2"
                >
                  <Plus size={16} /> ใส่ตระกร้า
                </button>
              </div>
            </div>
          ))}
        </div>
      </main>

      {/* Cart Sidebar/Modal */}
      {isCartOpen && (
        <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex justify-end">
            <div className="bg-white w-full max-w-md h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

                {/* Cart Header */}
                <div className="p-4 bg-orange-50 border-b border-orange-100 flex justify-between items-center">
                    <h2 className="text-xl font-bold flex items-center gap-2">
                        <ShoppingCart className="text-orange-600"/> ตะกร้าสินค้า
                    </h2>
                    <button onClick={() => setIsCartOpen(false)} className="p-2 hover:bg-orange-100 rounded-full">
                        <X size={24} className="text-gray-500" />
                    </button>
                </div>

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-4 space-y-4">
                    {cart.length === 0 ? (
                        <div className="text-center text-gray-400 mt-20">
                            <ShoppingCart size={48} className="mx-auto mb-4 opacity-30"/>
                            <p>ยังไม่มีสินค้าในตระกร้า</p>
                            <button onClick={() => setIsCartOpen(false)} className="mt-4 text-orange-600 font-medium">ไปเลือกอาหารกันเถอะ</button>
                        </div>
                    ) : (
                        cart.map(item => (
                            <div key={item.id} className="flex gap-4 items-center bg-white p-2 rounded-lg border border-gray-100 shadow-sm">
                                <div className="w-16 h-16 rounded-md bg-gray-100 overflow-hidden flex-shrink-0">
                                    <img src={item.image} alt={item.name} className="w-full h-full object-cover"/>
                                </div>
                                <div className="flex-1">
                                    <h4 className="font-semibold text-gray-800 text-sm">{item.name}</h4>
                                    <p className="text-orange-600 font-bold text-sm">{item.price * item.quantity} ฿</p>
                                </div>
                                <div className="flex items-center gap-2 bg-gray-50 rounded-lg p-1">
                                    <button 
                                        onClick={() => item.quantity === 1 ? removeFromCart(item.id) : updateQuantity(item.id, -1)}
                                        className="p-1 hover:bg-white rounded-md shadow-sm text-gray-600"
                                    >
                                        <Minus size={14} />
                                    </button>
                                    <span className="text-sm font-medium w-4 text-center">{item.quantity}</span>
                                    <button 
                                        onClick={() => updateQuantity(item.id, 1)}
                                        className="p-1 hover:bg-white rounded-md shadow-sm text-gray-600"
                                    >
                                        <Plus size={14} />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Checkout Form */}
                {cart.length > 0 && (
                    <div className="p-4 border-t border-gray-100 bg-gray-50 space-y-4">
                        <div className="space-y-2">
                             <h3 className="font-semibold text-gray-700 flex items-center gap-2">
                                <MapPin size={16} /> ข้อมูลจัดส่ง
                             </h3>
                             <input 
                                type="text" 
                                placeholder="ชื่อผู้รับ" 
                                className="w-full p-2 rounded-md border text-sm"
                                value={customerName}
                                onChange={(e) => setCustomerName(e.target.value)}
                             />
                             <input 
                                type="tel" 
                                placeholder="เบอร์โทรศัพท์" 
                                className="w-full p-2 rounded-md border text-sm"
                                value={customerPhone}
                                onChange={(e) => setCustomerPhone(e.target.value)}
                             />
                             <div className="mt-2">
                                 <label className="text-xs text-gray-500 mb-1 block">ปักหมุดที่อยู่:</label>
                                 <MapPicker onLocationSelect={setLocation} />
                             </div>
                        </div>

                        <div className="flex justify-between items-center text-lg font-bold border-t pt-4 border-gray-200">
                            <span>ยอดรวมสุทธิ</span>
                            <span className="text-orange-600">{total} ฿</span>
                        </div>

                        <button 
                            onClick={sendToLine}
                            className="w-full bg-[#06C755] hover:bg-[#05b64d] text-white py-3 rounded-xl font-bold text-lg shadow-md hover:shadow-lg transition flex items-center justify-center gap-2"
                        >
                            <Send size={20} /> ยืนยันคำสั่งซื้อทาง LINE
                        </button>
                        <p className="text-[10px] text-gray-400 text-center">
                            ระบบจะสร้างข้อความสรุปรายการอาหารเพื่อให้คุณส่งต่อให้ทางร้านใน LINE
                        </p>
                    </div>
                )}
            </div>
        </div>
      )}

    </div>
  );
};

export default App;

