      <div className="text-xs text-center text-gray-500 mt-1">
        *แตะที่แผนที่เพื่อปักหมุดจุดส่งอาหาร (Tap map to pin location)
      </div>
    </div>
  );
};

import * as XLSX from 'xlsx';
import { MenuItem } from '../types';

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vQHMMZknmvaNUkgBWkWnxtqRiDkgYfCcNcWuvUhH2uVSfqOOwPL232u566GkkusqA/pub?output=xlsx';

// Helper to convert Google Drive links to direct image links
const processImageUrl = (url: string): string => {
  if (!url) return '';
  let cleanUrl = url.trim();

  // Check if it is a Google Drive link
  if (cleanUrl.includes('drive.google.com')) {
    // Try to extract the ID
    const idMatch = cleanUrl.match(/\/d\/(.*?)\/|id=(.*?)(&|$)/);
    if (idMatch) {
      const id = idMatch[1] || idMatch[2];
      // Convert to a direct view link
      return `https://drive.google.com/uc?export=view&id=${id}`;
    }
  }

  return cleanUrl;
};

export const fetchMenuFromSheet = async (): Promise<MenuItem[]> => {
  try {
    const response = await fetch(SHEET_URL);
    if (!response.ok) {
      throw new Error('Failed to fetch menu data');
    }

    const arrayBuffer = await response.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });

    // Assume the first sheet is the menu
    const sheetName = workbook.SheetNames[0];
    const sheet = workbook.Sheets[sheetName];

    // Convert to JSON
    const rawData = XLSX.utils.sheet_to_json<any>(sheet);

    // Normalize keys and map to our MenuItem type
    return rawData.map((row, index) => {
      // Helper to find value regardless of case
      const getValue = (keys: string[]) => {
        const foundKey = Object.keys(row).find(k => keys.some(searchKey => k.toLowerCase().includes(searchKey)));
        return foundKey ? row[foundKey] : undefined;
      };

      // Expanded search terms
      const name = getValue(['name', 'menu', 'item', 'food', 'ชื่อ', 'รายการ', 'เมนู']);
      const price = getValue(['price', 'cost', 'ราคา', 'บาท']);
      const category = getValue(['category', 'type', 'หมวด', 'ประเภท', 'group']);
      const desc = getValue(['description', 'detail', 'รายละเอียด', 'ส่วนประกอบ', 'คำอธิบาย']);

      // Look for image columns more aggressively
      const rawImg = getValue(['image', 'img', 'url', 'photo', 'รูป', 'pic', 'link']);
      const processedImg = rawImg ? processImageUrl(String(rawImg)) : `https://picsum.photos/seed/${index}/300/200`;

      return {
        id: `item-${index}`,
        name: name || `Menu Item ${index + 1}`,
        price: Number(price) || 0,
        category: String(category || 'General'),
        description: desc ? String(desc) : undefined,
        image: processedImg,
        isSpicy: String(name).includes('Spicy') || String(desc).includes('พริก') || String(name).includes('ต้มยำ') || String(name).includes('เผ็ด'),
      };
    }).filter(item => item.name && item.price > 0); // Filter out empty or invalid rows

  } catch (error) {
    console.error("Error loading menu:", error);
    // Return a fallback menu if the sheet fails
    return [
      { id: '1', name: 'ข้าวกะเพราไก่ไข่ดาว', price: 60, category: 'อาหารจานเดียว', description: 'เผ็ดจัดจ้าน', isSpicy: true, image: 'https://picsum.photos/seed/krapow/300/200' },
      { id: '2', name: 'ข้าวผัดหมู', price: 55, category: 'อาหารจานเดียว', description: 'ผัดหอมกะทะ', isSpicy: false, image: 'https://picsum.photos/seed/friedrice/300/200' },
      { id: '3', name: 'ต้มยำกุ้ง', price: 120, category: 'กับข้าว', description: 'น้ำข้น', isSpicy: true, image: 'https://picsum.photos/seed/tomyum/300/200' },
    ];
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { ShoppingCart, MapPin, Send, MessageCircle, X, Plus, Minus, Search, Loader2, Info, ChevronRight, Store } from 'lucide-react';
import { MenuItem, CartItem, LocationState } from './types';
import { fetchMenuFromSheet } from './services/menuService';
import { getFoodRecommendation } from './services/geminiService';
import { MapPicker } from './components/MapPicker';

const App: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  // Item Detail Modal State
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [tempQuantity, setTempQuantity] = useState(1);
  const [tempNote, setTempNote] = useState('');

  // Checkout State
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [location, setLocation] = useState<LocationState | null>(null);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [showAi, setShowAi] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      const data = await fetchMenuFromSheet();
      setMenu(data);
      setLoading(false);
    };
    loadData();
  }, []);

  // Derived state for categories
  const categories = useMemo(() => {
    const cats = Array.from(new Set(menu.map(item => item.category))).filter(Boolean);
    return ['All', ...cats];
  }, [menu]);

  const filteredMenu = useMemo(() => {
    if (selectedCategory === 'All') return menu;
    return menu.filter(item => item.category === selectedCategory);
  }, [menu, selectedCategory]);

  const openItemModal = (item: MenuItem) => {
    setSelectedItem(item);
    setTempQuantity(1);
    setTempNote('');
  };

  const closeItemModal = () => {
    setSelectedItem(null);
  };

  const confirmAddToCart = () => {
    if (!selectedItem) return;

    setCart(prev => {
      // Check if same item WITH SAME NOTE exists
      const existingIndex = prev.findIndex(
        i => i.id === selectedItem.id && i.note === tempNote
      );

      if (existingIndex >= 0) {
        const newCart = [...prev];
        newCart[existingIndex].quantity += tempQuantity;
        return newCart;
      }

      return [...prev, { 
        ...selectedItem, 
        quantity: tempQuantity, 
        note: tempNote 
      }];
    });

    closeItemModal();
    // Optional: Give feedback
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const updateQuantity = (index: number, delta: number) => {
    setCart(prev => prev.map((item, i) => {
      if (i === index) {
        const newQ = item.quantity + delta;
        return newQ > 0 ? { ...item, quantity: newQ } : item;
      }
      return item;
    }));
  };

  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    const answer = await getFoodRecommendation(aiQuery, menu);
    setAiResponse(answer);
    setIsAiLoading(false);
  };

  const generateLineMessage = () => {
    let msg = `🛒 *New Order from ArhanDuan*\n\n`;
    msg += `👤 Customer: ${customerName}\n`;
    msg += `📞 Tel: ${customerPhone}\n`;
    msg += `📍 Location: ${location ? `https://www.google.com/maps?q=${location.lat},${location.lng}` : 'Not provided'}\n\n`;
    msg += `📋 *Items:*\n`;
    cart.forEach(item => {
      msg += `- ${item.name} x${item.quantity}`;
      if (item.note) msg += `\n  (Note: ${item.note})`;
      msg += `\n  ${item.price * item.quantity}฿\n`;
    });
    msg += `\n💰 *Total: ${total} THB*`;

    return encodeURIComponent(msg);
  };

  const sendToLine = () => {
    if (!customerName || !customerPhone || cart.length === 0) {
      alert("Please fill in your name, phone and select items.");
      return;
    }
    const message = generateLineMessage();
    window.open(`https://line.me/R/msg/text/?${message}`, '_blank');
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-orange-50">
        <div className="text-center">
          <Loader2 className="w-10 h-10 animate-spin text-orange-500 mx-auto mb-2" />
          <p className="text-orange-600 font-medium">กำลังโหลดเมนูอร่อยๆ...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-24 relative max-w-5xl mx-auto bg-gray-50 shadow-xl overflow-hidden">

      {/* Header */}
