import * as XLSX from 'xlsx';
import { MenuItem, MenuOption } from '../types';

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vQHMMZknmvaNUkgBWkWnxtqRiDkgYfCcNcWuvUhH2uVSfqOOwPL232u566GkkusqA/pub?output=xlsx';

// Helper to convert Google Drive links to direct image links
const processImageUrl = (url: string): string => {
  if (!url) return '';
  let cleanUrl = url.trim();

  // Check if it is a Google Drive link
  if (cleanUrl.includes('drive.google.com')) {
    // Try to extract the ID
    const idMatch = cleanUrl.match(/\/d\/(.*?)\/|id=(.*?)(&|$)/);
    if (idMatch) {
      const id = idMatch[1] || idMatch[2];
      // Convert to a direct view link
      return `https://drive.google.com/uc?export=view&id=${id}`;
    }
  }

  return cleanUrl;
};

// Helper to parse options string like "Meat: Pork, Chicken | Level: 1, 2"
const processOptions = (raw: string): MenuOption[] => {
  if (!raw) return [];

  try {
    return raw.split('|').map(group => {
      const [name, choicesStr] = group.split(':').map(s => s.trim());
      if (!name || !choicesStr) return null;

      const choices = choicesStr.split(',').map(s => s.trim()).filter(s => s.length > 0);
      return { name, choices };
    }).filter((opt): opt is MenuOption => opt !== null && opt.choices.length > 0);
  } catch (e) {
    console.error("Error parsing options:", raw, e);
    return [];
  }
};

export const fetchMenuFromSheet = async (): Promise<MenuItem[]> => {
  try {
    const response = await fetch(SHEET_URL);
    if (!response.ok) {
      throw new Error('Failed to fetch menu data');
    }

    const arrayBuffer = await response.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });

    // Assume the first sheet is the menu
    const sheetName = workbook.SheetNames[0];
    const sheet = workbook.Sheets[sheetName];

    // Convert to JSON
    const rawData = XLSX.utils.sheet_to_json<any>(sheet);

    // Normalize keys and map to our MenuItem type
    return rawData.map((row, index) => {
      // Helper to find value regardless of case
      const getValue = (keys: string[]) => {
        const foundKey = Object.keys(row).find(k => keys.some(searchKey => k.toLowerCase().includes(searchKey)));
        return foundKey ? row[foundKey] : undefined;
      };

      // Expanded search terms
      const name = getValue(['name', 'menu', 'item', 'food', 'ชื่อ', 'รายการ', 'เมนู']);
      const price = getValue(['price', 'cost', 'ราคา', 'บาท']);
      const category = getValue(['category', 'type', 'หมวด', 'ประเภท', 'group']);
      const desc = getValue(['description', 'detail', 'รายละเอียด', 'ส่วนประกอบ', 'คำอธิบาย']);

      // Look for image columns more aggressively
      const rawImg = getValue(['image', 'img', 'url', 'photo', 'รูป', 'pic', 'link']);
      const processedImg = rawImg ? processImageUrl(String(rawImg)) : `https://picsum.photos/seed/${index}/300/200`;

      // Parse options
      const rawOptions = getValue(['option', 'choice', 'selection', 'ตัวเลือก', 'add-on']);
      const options = rawOptions ? processOptions(String(rawOptions)) : [];

      return {
        id: `item-${index}`,
        name: name || `Menu Item ${index + 1}`,
        price: Number(price) || 0,
        category: String(category || 'General'),
        description: desc ? String(desc) : undefined,
        image: processedImg,
        isSpicy: String(name).includes('Spicy') || String(desc).includes('พริก') || String(name).includes('ต้มยำ') || String(name).includes('เผ็ด'),
        options: options
      };
    }).filter(item => item.name && item.price > 0); // Filter out empty or invalid rows

  } catch (error) {
    console.error("Error loading menu:", error);
    // Return a fallback menu if the sheet fails
    return [
      { 
        id: '1', 
        name: 'ข้าวกะเพรา', 
        price: 60, 
        category: 'อาหารจานเดียว', 
        description: 'ผัดแห้งๆ หอมๆ', 
        isSpicy: true, 
        image: 'https://picsum.photos/seed/krapow/300/200',
        options: [
           { name: 'เนื้อสัตว์', choices: ['ไก่', 'หมูสับ', 'หมูกรอบ'] },
           { name: 'ไข่ดาว', choices: ['ไม่รับ', 'ไข่ดาว (+10)'] }
        ]
      },
      { id: '2', name: 'ข้าวผัดหมู', price: 55, category: 'อาหารจานเดียว', description: 'ผัดหอมกะทะ', isSpicy: false, image: 'https://picsum.photos/seed/friedrice/300/200' },
      { id: '3', name: 'ต้มยำกุ้ง', price: 120, category: 'กับข้าว', description: 'น้ำข้น', isSpicy: true, image: 'https://picsum.photos/seed/tomyum/300/200' },
    ];
  }
};

import React, { useState, useEffect, useMemo } from 'react';
