                                            <button 
                                                onClick={() => updateQuantity(index, 1)}
                                                className="w-6 h-6 flex items-center justify-center bg-white rounded shadow-sm text-gray-600"
                                            >
                                                <Plus size={12} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Checkout Form */}
                {cart.length > 0 && (
                    <div className="bg-white p-5 border-t border-gray-100 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                        <div className="space-y-3 mb-4">
                             <div className="flex items-center gap-2 text-gray-700 font-semibold mb-2">
                                <MapPin size={18} className="text-orange-500"/> 
                                <span>จัดส่งที่ไหนดี?</span>
                             </div>
                             <div className="grid grid-cols-2 gap-2">
                                <input 
                                    type="text" 
                                    placeholder="ชื่อของคุณ" 
                                    className="p-2.5 bg-gray-50 border-transparent focus:bg-white border focus:border-orange-300 rounded-lg text-sm outline-none transition"
                                    value={customerName}
                                    onChange={(e) => setCustomerName(e.target.value)}
                                />
                                <input 
                                    type="tel" 
                                    placeholder="เบอร์โทร" 
                                    className="p-2.5 bg-gray-50 border-transparent focus:bg-white border focus:border-orange-300 rounded-lg text-sm outline-none transition"
                                    value={customerPhone}
                                    onChange={(e) => setCustomerPhone(e.target.value)}
                                />
                             </div>
                             <div className="rounded-lg overflow-hidden border border-gray-200">
                                 <MapPicker onLocationSelect={setLocation} />
                             </div>
                        </div>

                        <div className="flex justify-between items-center text-lg font-bold py-3 border-t border-dashed border-gray-200">
                            <span>ยอดรวมทั้งหมด</span>
                            <span className="text-orange-600 text-xl">{total} ฿</span>
                        </div>

                        <button 
                            onClick={sendToLine}
                            className="w-full bg-[#06C755] hover:bg-[#05b64d] active:scale-[0.98] text-white py-3.5 rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition flex items-center justify-center gap-2"
                        >
                            <Send size={22} /> สั่งอาหารทาง LINE
                        </button>
                    </div>
                )}
            </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { ShoppingCart, MapPin, Send, MessageCircle, X, Plus, Minus, Search, Loader2, Info, ChevronRight, Store, RotateCcw } from 'lucide-react';
import { MenuItem, CartItem, LocationState } from './types';
import { fetchMenuFromSheet } from './services/menuService';
import { getFoodRecommendation } from './services/geminiService';
import { MapPicker } from './components/MapPicker';

const App: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  // Item Detail Modal State
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [tempQuantity, setTempQuantity] = useState(1);
  const [tempNote, setTempNote] = useState('');
  const [tempSelectedOptions, setTempSelectedOptions] = useState<Record<string, string>>({});
  const [isTakeaway, setIsTakeaway] = useState(false); // New state for takeaway

  // Checkout State
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [location, setLocation] = useState<LocationState | null>(null);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [showAi, setShowAi] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      const data = await fetchMenuFromSheet();
      setMenu(data);
      setLoading(false);
    };
    loadData();
  }, []);

  // Derived state for categories
  const categories = useMemo(() => {
    const cats = Array.from(new Set(menu.map(item => item.category))).filter(Boolean);
    return ['All', ...cats];
  }, [menu]);

  const filteredMenu = useMemo(() => {
    if (selectedCategory === 'All') return menu;
    return menu.filter(item => item.category === selectedCategory);
  }, [menu, selectedCategory]);

  const openItemModal = (item: MenuItem) => {
    setSelectedItem(item);
    setTempQuantity(1);
    setTempNote('');
    setIsTakeaway(false); // Reset takeaway

    // Initialize default options (select the first choice of each group)
    const defaultOpts: Record<string, string> = {};
    if (item.options) {
      item.options.forEach(opt => {
        if (opt.choices.length > 0) {
          defaultOpts[opt.name] = opt.choices[0];
        }
      });
    }
    setTempSelectedOptions(defaultOpts);
  };

  const closeItemModal = () => {
    setSelectedItem(null);
  };

  const handleOptionChange = (optionName: string, choice: string) => {
    setTempSelectedOptions(prev => ({
      ...prev,
      [optionName]: choice
    }));
  };

  const resetModal = () => {
      if(selectedItem) openItemModal(selectedItem);
  };

  const confirmAddToCart = () => {
    if (!selectedItem) return;

    // Create a unique key for options comparison
    const optionsKey = JSON.stringify(tempSelectedOptions);

    // Append takeaway to note if selected
    let finalNote = tempNote;
    if (isTakeaway) {
        finalNote = finalNote ? `(กลับบ้าน) ${finalNote}` : '(กลับบ้าน)';
    }

    setCart(prev => {
      // Check if same item WITH SAME NOTE AND SAME OPTIONS exists
      const existingIndex = prev.findIndex(
        i => i.id === selectedItem.id && 
             i.note === finalNote && 
             JSON.stringify(i.selectedOptions) === optionsKey
      );

      if (existingIndex >= 0) {
        const newCart = [...prev];
        newCart[existingIndex].quantity += tempQuantity;
        return newCart;
      }

      return [...prev, { 
        ...selectedItem, 
        quantity: tempQuantity, 
        note: finalNote,
        selectedOptions: { ...tempSelectedOptions }
      }];
    });

    closeItemModal();
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const updateQuantity = (index: number, delta: number) => {
    setCart(prev => prev.map((item, i) => {
      if (i === index) {
        const newQ = item.quantity + delta;
        return newQ > 0 ? { ...item, quantity: newQ } : item;
      }
      return item;
    }));
  };

  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    const answer = await getFoodRecommendation(aiQuery, menu);
    setAiResponse(answer);
    setIsAiLoading(false);
  };

  const generateLineMessage = () => {
    let msg = `🛒 *New Order from ArhanDuan*\n\n`;
    msg += `👤 Customer: ${customerName}\n`;
    msg += `📞 Tel: ${customerPhone}\n`;
    msg += `📍 Location: ${location ? `https://www.google.com/maps?q=${location.lat},${location.lng}` : 'Not provided'}\n\n`;
    msg += `📋 *Items:*\n`;
    cart.forEach(item => {
      msg += `- ${item.name} x${item.quantity}`;

      // Format options
      if (item.selectedOptions && Object.keys(item.selectedOptions).length > 0) {
        const optStr = Object.entries(item.selectedOptions)
          .map(([key, val]) => `${key}: ${val}`)
          .join(', ');
        msg += `\n   (${optStr})`;
      }

      if (item.note) msg += `\n   Note: ${item.note}`;
      msg += `\n   ${item.price * item.quantity}฿\n`;
    });
    msg += `\n💰 *Total: ${total} THB*`;

    return encodeURIComponent(msg);
  };

  const sendToLine = () => {
    if (!customerName || !customerPhone || cart.length === 0) {
      alert("Please fill in your name, phone and select items.");
      return;
    }
    const message = generateLineMessage();
    window.open(`https://line.me/R/msg/text/?${message}`, '_blank');
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-orange-50">
        <div className="text-center">
          <Loader2 className="w-10 h-10 animate-spin text-orange-500 mx-auto mb-2" />
          <p className="text-orange-600 font-medium">กำลังโหลดเมนูอร่อยๆ...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-24 relative max-w-5xl mx-auto bg-gray-50 shadow-xl overflow-hidden">

      {/* Header */}
      <header className="sticky top-0 z-40 bg-white shadow-sm px-4 py-3 flex justify-between items-center">
        <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-orange-100 rounded-full flex items-center justify-center text-orange-600">
                <Store size={20} />
            </div>
            <div>
                 <h1 className="text-lg font-bold text-gray-800 leading-tight">อาหารด่วน! 🛵</h1>
                 <p className="text-[10px] text-gray-500">สั่งเลย อร่อยทุกเมนู</p>
            </div>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setShowAi(!showAi)}
                className={`p-2 rounded-full transition ${showAi ? 'bg-orange-100 text-orange-600' : 'bg-gray-100 text-gray-600'}`}
            >
                <MessageCircle size={22} />
            </button>
            <button 
                onClick={() => setIsCartOpen(true)}
                className="relative p-2 bg-orange-600 text-white rounded-full hover:bg-orange-700 transition shadow-md"
            >
                <ShoppingCart size={22} />
                {cart.length > 0 && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border border-white">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                    </span>
                )}
            </button>
        </div>
      </header>

      {/* AI Assistant Panel */}
      {showAi && (
        <div className="bg-orange-50 p-4 border-b border-orange-200 animate-in slide-in-from-top duration-300">
            <h3 className="font-bold text-orange-800 mb-2 flex items-center gap-2 text-sm">
                <Info size={16}/> ผู้ช่วยแนะนำอาหาร (AI Waiter)
            </h3>
            <div className="flex gap-2 mb-3">
                <input 
                    type="text" 
                    value={aiQuery}
                    onChange={(e) => setAiQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()}
                    placeholder="เช่น อยากทานของเผ็ดๆ..."
                    className="flex-1 p-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-orange-400"
                />
                <button 
                    onClick={handleAiAsk}
                    disabled={isAiLoading}
                    className="bg-orange-500 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-orange-600 disabled:opacity-50"
                >
                    {isAiLoading ? <Loader2 className="animate-spin w-4 h-4"/> : 'ถาม'}
                </button>
            </div>
            {aiResponse && (
                <div className="bg-white p-3 rounded-lg text-sm text-gray-700 shadow-sm border border-orange-100 whitespace-pre-wrap">
                    {aiResponse}
                </div>
            )}
        </div>
      )}

      {/* Category Tabs */}
      <div className="sticky top-[64px] z-30 bg-white border-b border-gray-100 shadow-sm">
        <div className="flex overflow-x-auto no-scrollbar py-3 px-4 gap-3">
            {categories.map(cat => (
                <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`whitespace-nowrap px-4 py-1.5 rounded-full text-sm font-medium transition-all ${
                        selectedCategory === cat 
                        ? 'bg-orange-600 text-white shadow-md' 
                        : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                    }`}
                >
                    {cat}
                </button>
            ))}
        </div>
      </div>

      {/* Menu List */}
      <main className="p-4 max-w-4xl mx-auto">
        <div className="space-y-4">
          {filteredMenu.map(item => (
            <div 
                key={item.id} 
                onClick={() => openItemModal(item)}
                className="bg-white rounded-xl p-3 shadow-sm border border-gray-100 flex gap-3 hover:shadow-md transition cursor-pointer active:scale-[0.99]"
            >
              {/* Image */}
              <div className="w-24 h-24 bg-gray-100 rounded-lg overflow-hidden flex-shrink-0 relative">
                 <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                 {item.isSpicy && (
                     <span className="absolute top-1 right-1 bg-red-500 text-white text-[8px] px-1.5 py-0.5 rounded-full font-bold shadow-sm">
                         Spicy
                     </span>
                 )}
              </div>

              {/* Content */}
              <div className="flex-1 flex flex-col justify-between">
                <div>
                    <div className="flex justify-between items-start">
                        <h3 className="font-bold text-gray-800 leading-tight line-clamp-2">{item.name}</h3>
                        <span className="font-bold text-orange-600 whitespace-nowrap ml-2">{item.price} ฿</span>
                    </div>
                    <p className="text-gray-400 text-xs mt-1 line-clamp-2">{item.description}</p>
                    {item.options && item.options.length > 0 && (
                      <p className="text-orange-500 text-[10px] mt-1 bg-orange-50 inline-block px-1 rounded">
                        มีตัวเลือกเพิ่มเติม
                      </p>
                    )}
                </div>
                <div className="flex justify-end mt-2">
                    <button className="bg-orange-50 text-orange-600 w-8 h-8 rounded-full flex items-center justify-center hover:bg-orange-100 transition">
                        <Plus size={18} />
                    </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </main>

      {/* Item Detail Modal */}
      {selectedItem && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
              <div className="bg-white w-full max-w-md rounded-2xl overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200 relative flex flex-col max-h-[90vh]">

                  {/* Header: Thumbnail + Title */}
                  <div className="p-4 border-b border-gray-100 flex gap-4 relative">
                      <button onClick={closeItemModal} className="absolute top-2 right-2 text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-100 transition">
                          <X size={24} />
                      </button>

                      <div className="w-20 h-20 rounded-lg overflow-hidden shrink-0 border border-gray-100">
                          <img src={selectedItem.image} alt={selectedItem.name} className="w-full h-full object-cover"/>
                      </div>
                      <div className="flex-1 pr-6 pt-1">
                          <h2 className="text-xl font-bold text-gray-800 leading-tight">{selectedItem.name}</h2>
                          <p className="text-gray-500 text-sm mt-1">ราคาเริ่มต้น {selectedItem.price} ฿</p>
                      </div>
                  </div>

                  {/* Content Scrollable Area */}
                  <div className="p-5 overflow-y-auto flex-1 bg-white">
                      {/* DYNAMIC OPTIONS RENDERER */}
                      {selectedItem.options && selectedItem.options.map((option, idx) => (
                        <div key={idx} className="mb-6">
                          <h4 className="font-bold text-gray-800 text-lg mb-3 flex items-center gap-1">
                            {option.name} <span className="text-red-500">*</span>
                          </h4>
                          <div className="space-y-3">
                            {option.choices.map((choice) => {
                              const isSelected = tempSelectedOptions[option.name] === choice;
                              return (
                                <label key={choice} className={`flex items-center p-3 rounded-xl border-2 cursor-pointer transition-all ${
                                  isSelected
                                    ? 'border-orange-500 bg-white ring-0' 
                                    : 'border-gray-100 hover:border-gray-200'
                                }`}>
                                  <div className={`w-5 h-5 rounded-full border-2 mr-3 flex items-center justify-center ${
                                      isSelected ? 'border-orange-500' : 'border-gray-300'
                                  }`}>
                                      {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-orange-500" />}
                                  </div>
                                  <span className="text-gray-700 text-base">{choice}</span>
                                  <input 
                                    type="radio" 
                                    name={`opt-${selectedItem.id}-${option.name}`}
                                    value={choice}
                                    checked={isSelected}
                                    onChange={() => handleOptionChange(option.name, choice)}
                                    className="hidden"
                                  />
                                </label>
                              );
                            })}
                          </div>
                        </div>
                      ))}

                      {/* Special Instructions */}
                      <div className="mb-4">
                          <label className="block text-lg font-bold text-gray-800 mb-2">หมายเหตุ (ถ้ามี):</label>
                          <textarea 
                             className="w-full border border-gray-300 rounded-lg p-3 text-sm focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none resize-none"
                             rows={3}
                             placeholder="เช่น ไม่ใส่น้ำตาล, น้ำมันน้อย"
                             value={tempNote}
                             onChange={(e) => setTempNote(e.target.value)}
                          />
                      </div>
                  </div>

                  {/* Footer Controls (Sticky Bottom) */}
                  <div className="p-4 bg-white border-t border-gray-100 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
                      <div className="flex items-center justify-between gap-4">
                          {/* Quantity (Blue Buttons) */}
                          <div className="flex items-center gap-3">
                              <button 
                                onClick={() => setTempQuantity(q => Math.max(1, q - 1))}
                                className="w-10 h-10 rounded-full bg-blue-500 hover:bg-blue-600 text-white flex items-center justify-center font-bold text-xl shadow-md transition"
                              >
                                  <Minus size={18} />
                              </button>
                              <span className="text-2xl font-bold text-gray-800 w-8 text-center">{tempQuantity}</span>
                              <button 
                                onClick={() => setTempQuantity(q => q + 1)}
                                className="w-10 h-10 rounded-full bg-blue-500 hover:bg-blue-600 text-white flex items-center justify-center font-bold text-xl shadow-md transition"
                              >
                                  <Plus size={18} />
                              </button>
                          </div>

                          <button onClick={resetModal} className="p-2 text-gray-400 hover:bg-gray-100 rounded-full">
                              <RotateCcw size={20} />
                          </button>

                          {/* Takeaway Checkbox */}
                          <label className="flex items-center gap-2 cursor-pointer select-none">
                              <div className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-colors ${isTakeaway ? 'bg-orange-500 border-orange-500' : 'border-gray-300'}`}>
                                  {isTakeaway && <CheckCircle size={14} className="text-white" />}
                              </div>
                              <input type="checkbox" className="hidden" checked={isTakeaway} onChange={(e) => setIsTakeaway(e.target.checked)} />
                              <span className="text-gray-600 font-medium text-sm whitespace-nowrap">สั่งกลับบ้าน</span>
                          </label>

                          {/* Add Button (Green) */}
                          <button 
                            onClick={confirmAddToCart}
                            className="bg-[#22c55e] hover:bg-[#16a34a] text-white px-4 py-3 rounded-lg font-bold text-lg shadow-lg transition flex-1"
                          >
                              เพิ่ม Order
                          </button>
                      </div>
                  </div>

              </div>
          </div>
      )}

      {/* Cart Sidebar */}
      {isCartOpen && (
        <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex justify-end">
            <div className="bg-white w-full max-w-md h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

                {/* Cart Header */}
                <div className="p-4 bg-orange-50 border-b border-orange-100 flex justify-between items-center shadow-sm">
                    <h2 className="text-lg font-bold flex items-center gap-2 text-gray-800">
                        <ShoppingCart className="text-orange-600" size={20}/> ตะกร้าสินค้า
                    </h2>
                    <button onClick={() => setIsCartOpen(false)} className="p-2 hover:bg-orange-100 rounded-full text-gray-500">
                        <X size={24} />
                    </button>
                </div>

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
                    {cart.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-full text-gray-400 space-y-4">
                            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center">
                                <ShoppingCart size={40} className="opacity-30"/>
                            </div>
                            <p>ยังไม่มีสินค้าในตระกร้า</p>
                            <button onClick={() => setIsCartOpen(false)} className="text-orange-600 font-medium hover:underline">ไปเลือกอาหารกันเถอะ</button>
                        </div>
                    ) : (
                        cart.map((item, index) => (
                            <div key={index} className="flex gap-3 bg-white p-3 rounded-xl border border-gray-100 shadow-sm relative">
                                <button 
                                    onClick={() => removeFromCart(index)}
                                    className="absolute top-2 right-2 text-gray-300 hover:text-red-500 p-1"
                                >
                                    <X size={16} />
                                </button>
                                <div className="w-16 h-16 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                                    <img src={item.image} alt={item.name} className="w-full h-full object-cover"/>
                                </div>
                                <div className="flex-1 pr-6">
                                    <h4 className="font-bold text-gray-800 text-sm">{item.name}</h4>

                                    {/* Display Selected Options */}
                                    {item.selectedOptions && Object.keys(item.selectedOptions).length > 0 && (
                                      <div className="mt-1 flex flex-wrap gap-1">
                                        {Object.entries(item.selectedOptions).map(([key, val]) => (
                                          <span key={key} className="text-[10px] bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded border border-orange-200">
                                            {val}
                                          </span>
                                        ))}
                                      </div>
                                    )}

                                    {item.note && (
                                        <p className="text-xs text-gray-500 italic mt-1">
                                            {item.note}
                                        </p>
                                    )}

                                    <div className="flex justify-between items-end mt-2">
                                        <p className="text-gray-900 font-bold text-sm">{item.price * item.quantity} ฿</p>
                                        <div className="flex items-center gap-2 bg-gray-50 rounded-lg p-0.5 border border-gray-200">
                                            <button 
                                                onClick={() => item.quantity === 1 ? removeFromCart(index) : updateQuantity(index, -1)}
                                                className="w-6 h-6 flex items-center justify-center bg-white rounded shadow-sm text-gray-600"
                                            >
                                                <Minus size={12} />
                                            </button>
                                            <span className="text-xs font-bold w-4 text-center">{item.quantity}</span>
                                            <button 
                                                onClick={() => updateQuantity(index, 1)}
                                                className="w-6 h-6 flex items-center justify-center bg-white rounded shadow-sm text-gray-600"
                                            >
                                                <Plus size={12} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Checkout Form */}
                {cart.length > 0 && (
                    <div className="bg-white p-5 border-t border-gray-100 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                        <div className="space-y-3 mb-4">
                             <div className="flex items-center gap-2 text-gray-700 font-semibold mb-2">
                                <MapPin size={18} className="text-orange-500"/> 
                                <span>จัดส่งที่ไหนดี?</span>
                             </div>
                             <div className="grid grid-cols-2 gap-2">
                                <input 
                                    type="text" 
                                    placeholder="ชื่อของคุณ" 
                                    className="p-2.5 bg-gray-50 border-transparent focus:bg-white border focus:border-orange-300 rounded-lg text-sm outline-none transition"
                                    value={customerName}
                                    onChange={(e) => setCustomerName(e.target.value)}
                                />
                                <input 
                                    type="tel" 
                                    placeholder="เบอร์โทร" 
                                    className="p-2.5 bg-gray-50 border-transparent focus:bg-white border focus:border-orange-300 rounded-lg text-sm outline-none transition"
                                    value={customerPhone}
                                    onChange={(e) => setCustomerPhone(e.target.value)}
                                />
                             </div>
                             <div className="rounded-lg overflow-hidden border border-gray-200">
                                 <MapPicker onLocationSelect={setLocation} />
                             </div>
                        </div>

                        <div className="flex justify-between items-center text-lg font-bold py-3 border-t border-dashed border-gray-200">
                            <span>ยอดรวมทั้งหมด</span>
                            <span className="text-orange-600 text-xl">{total} ฿</span>
                        </div>

                        <button 
                            onClick={sendToLine}
                            className="w-full bg-[#06C755] hover:bg-[#05b64d] active:scale-[0.98] text-white py-3.5 rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition flex items-center justify-center gap-2"
                        >
                            <Send size={22} /> สั่งอาหารทาง LINE
                        </button>
                    </div>
                )}
            </div>
        </div>
      )}

    </div>
  );
};

export default App;

