import * as XLSX from 'xlsx';
import { MenuItem, MenuOption } from '../types';

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/e/2PACX-1vQHMMZknmvaNUkgBWkWnxtqRiDkgYfCcNcWuvUhH2uVSfqOOwPL232u566GkkusqA/pub?output=xlsx';

// Helper to convert Google Drive links to direct image links
const processImageUrl = (url: string): string => {
  if (!url) return '';
  let cleanUrl = url.trim();

  // Check if it is a Google Drive link
  if (cleanUrl.includes('drive.google.com')) {
    // Try to extract the ID
    const idMatch = cleanUrl.match(/\/d\/(.*?)\/|id=(.*?)(&|$)/);
    if (idMatch) {
      const id = idMatch[1] || idMatch[2];
      // Convert to a direct view link
      return `https://drive.google.com/uc?export=view&id=${id}`;
    }
  }

  return cleanUrl;
};

// Helper to parse options string like "Meat: Pork, Chicken | Level: 1, 2"
const processOptions = (raw: string): MenuOption[] => {
  if (!raw) return [];

  try {
    if (raw.includes(':')) {
        return raw.split('|').map(group => {
            const [name, choicesStr] = group.split(':').map(s => s.trim());
            if (!name || !choicesStr) return null;

            const choices = choicesStr.split(',').map(s => s.trim()).filter(s => s.length > 0);
            return { name, choices };
        }).filter((opt): opt is MenuOption => opt !== null && opt.choices.length > 0);
    }
    return [];
  } catch (e) {
    console.error("Error parsing options:", raw, e);
    return [];
  }
};

export const fetchMenuFromSheet = async (): Promise<MenuItem[]> => {
  try {
    const response = await fetch(SHEET_URL);
    if (!response.ok) {
      throw new Error('Failed to fetch menu data');
    }

    const arrayBuffer = await response.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });

    // Assume the first sheet is the menu
    const sheetName = workbook.SheetNames[0];
    const sheet = workbook.Sheets[sheetName];

    // Convert to JSON
    const rawData = XLSX.utils.sheet_to_json<any>(sheet);

    // Group items by name to handle duplicates/options rows
    const groupedItems: Record<string, MenuItem> = {};

    rawData.forEach((row, index) => {
      // Helper to find value regardless of case or partial match
      const getValue = (keys: string[]) => {
        const foundKey = Object.keys(row).find(k => keys.some(searchKey => k.toLowerCase() === searchKey.toLowerCase() || k.toLowerCase().includes(searchKey.toLowerCase())));
        return foundKey ? row[foundKey] : undefined;
      };

      const name = getValue(['name', 'menu', 'item', 'food', 'ชื่อ', 'รายการ', 'เมนู']);
      if (!name) return; // Skip invalid rows

      // If item doesn't exist yet, create it
      if (!groupedItems[name]) {
          const price = getValue(['price', 'cost', 'ราคา', 'บาท']);
          const category = getValue(['category', 'type', 'หมวด', 'ประเภท', 'group']);
          const desc = getValue(['description', 'detail', 'รายละเอียด', 'ส่วนประกอบ', 'คำอธิบาย']);

          const rawImg = getValue(['image', 'img', 'url', 'photo', 'รูป', 'pic', 'link']);
          // Use name for seed to keep image consistent across reloads/duplicates if placeholder
          const processedImg = rawImg ? processImageUrl(String(rawImg)) : `https://picsum.photos/seed/${String(name).replace(/\s/g, '')}/300/200`;

          groupedItems[name] = {
            id: `item-${Object.keys(groupedItems).length}`,
            name: String(name),
            price: Number(price) || 0,
            category: String(category || 'General'),
            description: desc ? String(desc) : undefined,
            image: processedImg,
            isSpicy: String(name).includes('Spicy') || (desc && String(desc).includes('พริก')) || String(name).includes('ต้มยำ') || String(name).includes('เผ็ด'),
            options: []
          };
      }

      const item = groupedItems[name];

      // --- Option Parsing Logic ---

      // Strategy 1: Check for "Split Columns" (User Request: option_name column)
      // e.g. Column "option_name" = "Meat", Column "choices" = "Pork, Chicken"
      const optName = getValue(['option_name', 'option_header', 'ชื่อตัวเลือก', 'หัวข้อตัวเลือก']);
      const optChoices = getValue(['option_choices', 'option_values', 'choices', 'selections', 'ตัวเลือก', 'values', 'choice']);

      let optionAdded = false;

      if (optName && optChoices) {
          const newChoices = String(optChoices).split(',').map(s => s.trim()).filter(s => s);
          if (newChoices.length > 0) {
              const existingOpt = item.options?.find(o => o.name === optName);
              if (existingOpt) {
                   // Deduplicate choices
                   const combined = new Set([...existingOpt.choices, ...newChoices]);
                   existingOpt.choices = Array.from(combined);
              } else {
                   item.options?.push({
                       name: String(optName),
                       choices: newChoices
                   });
              }
              optionAdded = true;
          }
      }

      // Strategy 2: Check for "Combined String" if Strategy 1 didn't trigger
      // e.g. Column "options" = "Meat: Pork, Chicken | Level: 1, 2"
      if (!optionAdded) {
          // Avoid conflict: 'ตัวเลือก' might be caught by Strategy 1 if matched there. 
          // Here we look for the generic column again but process it differently.
          const rawOptions = getValue(['option_string', 'all_options', 'options', 'option', 'add-on', 'ตัวเลือก']);
          if (rawOptions && String(rawOptions).includes(':')) {
              const parsed = processOptions(String(rawOptions));
              parsed.forEach(p => {
                  const existingOpt = item.options?.find(o => o.name === p.name);
                  if (existingOpt) {
                      const combined = new Set([...existingOpt.choices, ...p.choices]);
                      existingOpt.choices = Array.from(combined);
                  } else {
                      item.options?.push(p);
                  }
              });
          }
      }
    });

    return Object.values(groupedItems);

  } catch (error) {
    console.error("Error loading menu:", error);
    // Return a fallback menu if the sheet fails
    return [
      { 
        id: '1', 
        name: 'ข้าวกะเพรา', 
        price: 60, 
        category: 'อาหารจานเดียว', 
        description: 'ผัดแห้งๆ หอมๆ', 
        isSpicy: true, 
        image: 'https://picsum.photos/seed/krapow/300/200',
        options: [
           { name: 'เนื้อสัตว์', choices: ['ไก่', 'หมูสับ', 'หมูกรอบ'] },
           { name: 'ไข่ดาว', choices: ['ไม่รับ', 'ไข่ดาว (+10)'] }
        ]
      },
      { id: '2', name: 'ข้าวผัดหมู', price: 55, category: 'อาหารจานเดียว', description: 'ผัดหอมกะทะ', isSpicy: false, image: 'https://picsum.photos/seed/friedrice/300/200' },
      { id: '3', name: 'ต้มยำกุ้ง', price: 120, category: 'กับข้าว', description: 'น้ำข้น', isSpicy: true, image: 'https://picsum.photos/seed/tomyum/300/200' },
    ];
  }
};

