      const optGroupKey = getValue(['option_group_name', 'group_name', 'option_group', 'หัวข้อตัวเลือก', 'กลุ่มตัวเลือก']);

      // Look for Choice Name (e.g. "หมู", "ไก่") - User said this is in 'option_name'
      const optChoiceKey = getValue(['option_name', 'choice_name', 'sub_option', 'ตัวเลือก', 'ชื่อตัวเลือก']);

      let optionAdded = false;

      // Case 1: Row-based (Group + Choice in specific columns)
      if (optGroupKey && optChoiceKey) {
          const groupName = String(optGroupKey).trim();
          const choiceName = String(optChoiceKey).trim();

          if (groupName && choiceName) {
              // Find if this group already exists in the item
              let existingGroup = item.options?.find(o => o.name === groupName);

              if (!existingGroup) {
                  existingGroup = { name: groupName, choices: [] };
                  item.options?.push(existingGroup);
              }

              // Add choice if not already there
              if (!existingGroup.choices.includes(choiceName)) {
                  existingGroup.choices.push(choiceName);
              }
              optionAdded = true;
          }
      }

      // Case 2: Comma separated choices in one cell (Backup strategy)
      // e.g. Column "option_name" = "Meat", Column "option_choices" = "Pork, Chicken"
      if (!optionAdded) {
          const optName = getValue(['option_header', 'หัวข้อ'], ['group']); // Fallback header
          const optChoices = getValue(['option_choices', 'choices', 'selections'], ['group', 'name']);

          if (optName && optChoices) {
               const newChoices = String(optChoices).split(',').map(s => s.trim()).filter(s => s);
               if (newChoices.length > 0) {
                   const existingOpt = item.options?.find(o => o.name === optName);
                   if (existingOpt) {
                        const combined = new Set([...existingOpt.choices, ...newChoices]);
                        existingOpt.choices = Array.from(combined);
                   } else {
                        item.options?.push({
                            name: String(optName),
                            choices: newChoices
                        });
                   }
               }
          }
      }
    });

    return Object.values(groupedItems);

  } catch (error) {
    console.error("Error loading menu:", error);
    // Return a fallback menu if the sheet fails
    return [
      { 
        id: '1', 
        name: 'ข้าวกะเพรา', 
        price: 60, 
        category: 'อาหารจานเดียว', 
        description: 'ผัดแห้งๆ หอมๆ', 
        isSpicy: true, 
        image: 'https://picsum.photos/seed/krapow/300/200',
        options: [
           { name: 'เนื้อสัตว์', choices: ['ไก่', 'หมูสับ', 'หมูกรอบ'] },
           { name: 'ไข่ดาว', choices: ['ไม่รับ', 'ไข่ดาว (+10)'] }
        ]
      },
      { id: '2', name: 'ข้าวผัดหมู', price: 55, category: 'อาหารจานเดียว', description: 'ผัดหอมกะทะ', isSpicy: false, image: 'https://picsum.photos/seed/friedrice/300/200' },
      { id: '3', name: 'ต้มยำกุ้ง', price: 120, category: 'กับข้าว', description: 'น้ำข้น', isSpicy: true, image: 'https://picsum.photos/seed/tomyum/300/200' },
    ];
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { ShoppingCart, MapPin, Send, MessageCircle, X, Plus, Minus, Search, Loader2, Info, ChevronRight, Store, RotateCcw } from 'lucide-react';
import { MenuItem, CartItem, LocationState } from './types';
import { fetchMenuFromSheet } from './services/menuService';
import { getFoodRecommendation } from './services/geminiService';
import { MapPicker } from './components/MapPicker';

const App: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  // Item Detail Modal State
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [tempQuantity, setTempQuantity] = useState(1);
  const [tempNote, setTempNote] = useState('');
  const [tempSelectedOptions, setTempSelectedOptions] = useState<Record<string, string>>({});

  // Checkout State
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [location, setLocation] = useState<LocationState | null>(null);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [showAi, setShowAi] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      const data = await fetchMenuFromSheet();
      setMenu(data);
      setLoading(false);
    };
    loadData();
  }, []);

  // Derived state for categories
  const categories = useMemo(() => {
    const cats = Array.from(new Set(menu.map(item => item.category))).filter(Boolean);
    return ['All', ...cats];
  }, [menu]);

  const filteredMenu = useMemo(() => {
    if (selectedCategory === 'All') return menu;
    return menu.filter(item => item.category === selectedCategory);
  }, [menu, selectedCategory]);

  const openItemModal = (item: MenuItem) => {
    setSelectedItem(item);
    setTempQuantity(1);
    setTempNote('');

    // Initialize default options (select the first choice of each group)
    const defaultOpts: Record<string, string> = {};
    if (item.options) {
      item.options.forEach(opt => {
        if (opt.choices.length > 0) {
          defaultOpts[opt.name] = opt.choices[0];
        }
      });
    }
    setTempSelectedOptions(defaultOpts);
  };

  const closeItemModal = () => {
    setSelectedItem(null);
  };

  const handleOptionChange = (optionName: string, choice: string) => {
    setTempSelectedOptions(prev => ({
      ...prev,
      [optionName]: choice
    }));
  };

  const resetModal = () => {
      if(selectedItem) openItemModal(selectedItem);
  };

  const confirmAddToCart = () => {
    if (!selectedItem) return;

    // Create a unique key for options comparison
    const optionsKey = JSON.stringify(tempSelectedOptions);

    setCart(prev => {
      // Check if same item WITH SAME NOTE AND SAME OPTIONS exists
      const existingIndex = prev.findIndex(
        i => i.id === selectedItem.id && 
             i.note === tempNote && 
             JSON.stringify(i.selectedOptions) === optionsKey
      );

      if (existingIndex >= 0) {
        const newCart = [...prev];
        newCart[existingIndex].quantity += tempQuantity;
        return newCart;
      }

      return [...prev, { 
        ...selectedItem, 
        quantity: tempQuantity, 
        note: tempNote,
        selectedOptions: { ...tempSelectedOptions }
      }];
    });

    closeItemModal();
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const updateQuantity = (index: number, delta: number) => {
    setCart(prev => prev.map((item, i) => {
      if (i === index) {
        const newQ = item.quantity + delta;
        return newQ > 0 ? { ...item, quantity: newQ } : item;
      }
      return item;
    }));
  };

  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    const answer = await getFoodRecommendation(aiQuery, menu);
    setAiResponse(answer);
    setIsAiLoading(false);
  };

  const generateLineMessage = () => {
    let msg = `🛒 *New Order from ArhanDuan*\n\n`;
    msg += `👤 Customer: ${customerName}\n`;
    msg += `📞 Tel: ${customerPhone}\n`;
    msg += `📍 Location: ${location ? `https://www.google.com/maps?q=${location.lat},${location.lng}` : 'Not provided'}\n\n`;
    msg += `📋 *Items:*\n`;
    cart.forEach(item => {
      msg += `- ${item.name} x${item.quantity}`;

      // Format options
      if (item.selectedOptions && Object.keys(item.selectedOptions).length > 0) {
        const optStr = Object.entries(item.selectedOptions)
          .map(([key, val]) => `${key}: ${val}`)
          .join(', ');
        msg += `\n   (${optStr})`;
      }

      if (item.note) msg += `\n   Note: ${item.note}`;
      msg += `\n   ${item.price * item.quantity}฿\n`;
    });
    msg += `\n💰 *Total: ${total} THB*`;

    return encodeURIComponent(msg);
  };

  const sendToLine = () => {
    if (!customerName || !customerPhone || cart.length === 0) {
      alert("Please fill in your name, phone and select items.");
      return;
    }
    const message = generateLineMessage();
    window.open(`https://line.me/R/msg/text/?${message}`, '_blank');
