            </div>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setShowAi(!showAi)}
                className={`p-2 rounded-full transition ${showAi ? 'bg-orange-100 text-orange-600' : 'bg-gray-100 text-gray-600'}`}
