                    <button onClick={() => setShowConfig(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={24}/>
                    </button>
                </div>

                <div className="space-y-6">
                    <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                        <p className="text-xs text-blue-800">
                            <strong>Note:</strong> การบันทึกที่นี่จะจำค่า <strong>เฉพาะบนเครื่องนี้เท่านั้น</strong> หากต้องการเปลี่ยนให้ลูกค้าทุกคนเห็น ต้องแก้ใน Google Sheet ครับ
                        </p>
